import sys
sys.setrecursionlimit(300000)

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx += 1
    M = int(input[idx]); idx += 1

    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        u = int(input[idx]); idx += 1
        v = int(input[idx]); idx += 1
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (N + 1)
    depth = [0] * (N + 1)
    up = [[0] * 20 for _ in range(N + 1)]

    order = []
    stack = [1]
    visited = [False] * (N + 1)
    visited[1] = True
    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                depth[v] = depth[u] + 1
                stack.append(v)

    for u in order:
        up[u][0] = parent[u]
        for j in range(1, 20):
            if up[u][j-1] != 0:
                up[u][j] = up[up[u][j-1]][j-1]

    def get_lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        for j in range(20):
            if (diff >> j) & 1:
                u = up[u][j]
        if u == v:
            return u
        for j in range(19, -1, -1):
            if up[u][j] != up[v][j]:
                u = up[u][j]
                v = up[v][j]
        return parent[u]

    def dist(u, v):
        lca = get_lca(u, v)
        return depth[u] + depth[v] - 2 * depth[lca]

    results = []
    for _ in range(M):
        P = int(input[idx]); idx += 1
        Q = int(input[idx]); idx += 1

        d_PQ = dist(P, Q)

        if d_PQ == 0:
            ans = 1
        else:
            ans = d_PQ + 1

        k = 1
        while True:
            next_k = k + 1
            if next_k > d_PQ + 1:
                break
            if k + next_k <= d_PQ + 1:
                k = next_k
            else:
                break

        if d_PQ == 0:
            k = 1
            while True:
                next_k = k + 1
                if next_k > N:
                    break
                if k + next_k <= N:
                    k = next_k
                else:
                    break
            ans = k + 1
        else:
            k = 1
            while True:
                next_step = k + 1
                if dist(P, Q) + next_step > N:
                    break
                if dist(P, Q) + next_step <= N:
                    k = next_step
                else:
                    break
            ans = k + 1

        results.append(str(ans))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    main()
